#!/bin/bash
set -e
cd /home/user

awk -F, 'NR==1{next} { svc=$1; stat=$2; rt=$3+0; cnt[svc]++; sum[svc]+=rt; if(stat=="success"){succ[svc]++}else{fail[svc]++} } END { print "service_name,total_checks,success_count,failure_count,avg_response_time_ms"; for(s in cnt){ avg=sum[s]/cnt[s]; printf "%s,%d,%d,%d,%.2f\n", s, cnt[s], succ[s]+0, fail[s]+0, avg } }' /home/user/obs-data/service_health.csv | sort -t, -k1,1 > /home/user/obs-data/service_health_summary.csv
awk -F, 'NR==1{next} { gsub(/"/,"\\\"",$0); if(NR>2)printf ","; printf "\n  {\"service_name\":\"%s\",\"total_checks\":%d,\"success_count\":%d,\"failure_count\":%d,\"avg_response_time_ms\":%.2f}", $1, $2, $3, $4, $5 } END{print ""}' /home/user/obs-data/service_health_summary.csv | awk 'BEGIN{print "["}{print}END{print "]"}' > /home/user/obs-data/service_health_summary.json
dt="$(date '+%Y-%m-%d %H:%M:%S')"; echo "[$dt] SUMMARY_CSV_CREATED: /home/user/obs-data/service_health_summary.csv" > /home/user/obs-data/dashboard_update.log; dt2="$(date '+%Y-%m-%d %H:%M:%S')"; echo "[$dt2] SUMMARY_JSON_CREATED: /home/user/obs-data/service_health_summary.json" >> /home/user/obs-data/dashboard_update.log
ls -1 /home/user/obs-data/ && head -20 /home/user/obs-data/service_health_summary.csv && head -20 /home/user/obs-data/service_health_summary.json && cat /home/user/obs-data/dashboard_update.log
awk 'NR==1{print; next} {print}' /home/user/obs-data/service_health_summary.csv | grep -v '^service_name,' | sort -t, -k1,1 | awk 'BEGIN{print "service_name,total_checks,success_count,failure_count,avg_response_time_ms"}{print}' > /home/user/obs-data/service_health_summary.csv
awk -F, 'NR==1{next} { svc=$1; stat=$2; rt=$3+0; cnt[svc]++; sum[svc]+=rt; if(stat=="success"){succ[svc]++}else{fail[svc]++} } END { for(s in cnt){ avg=sum[s]/cnt[s]; printf "%s,%d,%d,%d,%.2f\n", s, cnt[s], succ[s]+0, fail[s]+0, avg } }' /home/user/obs-data/service_health.csv | sort -t, -k1,1 | awk 'BEGIN{print "service_name,total_checks,success_count,failure_count,avg_response_time_ms"}{print}' > /home/user/obs-data/service_health_summary.csv
awk -F, 'NR==1{next} { if(NR>2)printf ","; printf "\n  {\"service_name\":\"%s\",\"total_checks\":%d,\"success_count\":%d,\"failure_count\":%d,\"avg_response_time_ms\":%.2f}", $1, $2, $3, $4, $5 } END{print ""}' /home/user/obs-data/service_health_summary.csv | awk 'BEGIN{print "["}{print}END{print "]"}' > /home/user/obs-data/service_health_summary.json
dt="$(date '+%Y-%m-%d %H:%M:%S')"; echo "[$dt] SUMMARY_CSV_CREATED: /home/user/obs-data/service_health_summary.csv" > /home/user/obs-data/dashboard_update.log; dt2="$(date '+%Y-%m-%d %H:%M:%S')"; echo "[$dt2] SUMMARY_JSON_CREATED: /home/user/obs-data/service_health_summary.json" >> /home/user/obs-data/dashboard_update.log
head -10 /home/user/obs-data/service_health_summary.csv; head -10 /home/user/obs-data/service_health_summary.json; cat /home/user/obs-data/dashboard_update.log
